import{_ as r,o as l,c as o,ah as n}from"./chunks/framework.DjU4PSOm.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"tags":["philosophy/Ethics"],"date":"2026-10-08T00:00:00.000Z"},"headers":[{"level":2,"title":"이 노트에 대하여","slug":"이-노트에-대하여","link":"#이-노트에-대하여","children":[]},{"level":2,"title":"1. 시작 질문 — 도시의 선택 (슬라이드 2쪽)","slug":"_1-시작-질문-—-도시의-선택-슬라이드-2쪽","link":"#_1-시작-질문-—-도시의-선택-슬라이드-2쪽","children":[]},{"level":2,"title":"2. 칸트 복습과 한계 (슬라이드 3~4쪽)","slug":"_2-칸트-복습과-한계-슬라이드-3-4쪽","link":"#_2-칸트-복습과-한계-슬라이드-3-4쪽","children":[]},{"level":2,"title":"3. 전환: 칸트 → 벤담 (슬라이드 5쪽)","slug":"_3-전환-칸트-→-벤담-슬라이드-5쪽","link":"#_3-전환-칸트-→-벤담-슬라이드-5쪽","children":[]},{"level":2,"title":"4. 벤담의 생애와 시대 (슬라이드 6쪽)","slug":"_4-벤담의-생애와-시대-슬라이드-6쪽","link":"#_4-벤담의-생애와-시대-슬라이드-6쪽","children":[]},{"level":2,"title":"5. 왜 \\"측정\\"인가 (슬라이드 7쪽)","slug":"_5-왜-측정-인가-슬라이드-7쪽","link":"#_5-왜-측정-인가-슬라이드-7쪽","children":[]},{"level":2,"title":"6. 핵심 개념 (슬라이드 8~9쪽)","slug":"_6-핵심-개념-슬라이드-8-9쪽","link":"#_6-핵심-개념-슬라이드-8-9쪽","children":[]},{"level":2,"title":"7. 양적 공리주의 (슬라이드 10쪽)","slug":"_7-양적-공리주의-슬라이드-10쪽","link":"#_7-양적-공리주의-슬라이드-10쪽","children":[]},{"level":2,"title":"8. 정독: 『도덕과 입법의 원리 서설』 4장, 29~30쪽 (슬라이드 11~12쪽)","slug":"_8-정독-『도덕과-입법의-원리-서설』-4장-29-30쪽-슬라이드-11-12쪽","link":"#_8-정독-『도덕과-입법의-원리-서설』-4장-29-30쪽-슬라이드-11-12쪽","children":[]},{"level":2,"title":"9. 절차: 한 사람에서 다수로 (슬라이드 13쪽)","slug":"_9-절차-한-사람에서-다수로-슬라이드-13쪽","link":"#_9-절차-한-사람에서-다수로-슬라이드-13쪽","children":[]},{"level":2,"title":"10. 주요 반론 (슬라이드 14~15쪽 + 요약)","slug":"_10-주요-반론-슬라이드-14-15쪽-요약","link":"#_10-주요-반론-슬라이드-14-15쪽-요약","children":[]},{"level":2,"title":"11. 현대적 적용 (슬라이드 16~17쪽)","slug":"_11-현대적-적용-슬라이드-16-17쪽","link":"#_11-현대적-적용-슬라이드-16-17쪽","children":[]},{"level":2,"title":"12. 두 가지 필수 질문과 핵심 정리 (슬라이드 18쪽)","slug":"_12-두-가지-필수-질문과-핵심-정리-슬라이드-18쪽","link":"#_12-두-가지-필수-질문과-핵심-정리-슬라이드-18쪽","children":[]},{"level":2,"title":"개념 깊이 보기","slug":"개념-깊이-보기","link":"#개념-깊이-보기","children":[{"level":3,"title":"7차원은 세 층으로 쌓인다","slug":"_7차원은-세-층으로-쌓인다","link":"#_7차원은-세-층으로-쌓인다","children":[]},{"level":3,"title":"순수성은 \\"높을수록 좋다\\"가 아니다","slug":"순수성은-높을수록-좋다-가-아니다","link":"#순수성은-높을수록-좋다-가-아니다","children":[]},{"level":3,"title":"심리적 → 윤리적 쾌락주의의 간극과 칸트","slug":"심리적-→-윤리적-쾌락주의의-간극과-칸트","link":"#심리적-→-윤리적-쾌락주의의-간극과-칸트","children":[]},{"level":3,"title":"같은 사례를 칸트와 벤담은 다르게 비판한다","slug":"같은-사례를-칸트와-벤담은-다르게-비판한다","link":"#같은-사례를-칸트와-벤담은-다르게-비판한다","children":[]},{"level":3,"title":"측정의 양면 — 판옵티콘","slug":"측정의-양면-—-판옵티콘","link":"#측정의-양면-—-판옵티콘","children":[]},{"level":3,"title":"경험 기계 — 쾌락주의에 대한 반례","slug":"경험-기계-—-쾌락주의에-대한-반례","link":"#경험-기계-—-쾌락주의에-대한-반례","children":[]}]}],"relativePath":"philosophy/Ethics/12. 벤담의 양적 공리주의(6주차 온라인).md","filePath":"philosophy/Ethics/12. 벤담의 양적 공리주의(6주차 온라인).md"}'),e={name:"philosophy/Ethics/12. 벤담의 양적 공리주의(6주차 온라인).md"};function i(s,t,a,d,g,h){return l(),o("div",null,[...t[0]||(t[0]=[n('<blockquote><p>📎 <strong>슬라이드 위치</strong>: <code>26-2 윤리학 6강.pdf</code> 2~18쪽 (시작 질문 ~ 칸트 복습·한계 ~ 칸트→벤담 전환 ~ 벤담의 시대 ~ 핵심 개념 ~ 쾌락 계산법 7차원 ~ 절차 ~ 반론 ~ 현대 적용 ~ 동물윤리) — 6-1·6-2 온라인 강의(10/3 업로드) 요약 자료 기준</p></blockquote><h2 id="이-노트에-대하여" tabindex="-1">이 노트에 대하여 <a class="header-anchor" href="#이-노트에-대하여" aria-label="Permalink to &quot;이 노트에 대하여&quot;">​</a></h2><p>6주차는 칸트(의무론)에서 <strong>벤담의 공리주의</strong>로 넘어가는 주다. 6-1, 6-2 온라인 강의 요약(영문·국문)을 <strong>슬라이드 순서대로</strong> 내 말로 정리했다. (원문: <a href="./Raw-Transcripts/2026-10-03_week6_online-summary.html">6주차 요약 원문</a>) 오프라인 6주차-3(10/12) 자막은 아직 없다.</p><hr><h2 id="_1-시작-질문-—-도시의-선택-슬라이드-2쪽" tabindex="-1">1. 시작 질문 — 도시의 선택 (슬라이드 2쪽) <a class="header-anchor" href="#_1-시작-질문-—-도시의-선택-슬라이드-2쪽" aria-label="Permalink to &quot;1. 시작 질문 — 도시의 선택 (슬라이드 2쪽)&quot;">​</a></h2><ul><li>예산을 한 사업에만 쓸 수 있다: <strong>(1)</strong> 희귀질환 10명을 위한 고비용 치료 vs <strong>(2)</strong> 10,000명을 위한 예방 의료 프로그램.</li><li>결정 전에 따져야 할 것: 질병의 심각성과 효과, 누가 얼마나 오래 혜택을 받는지, 하나를 거부했을 때 심각한 해악이 생기는지.</li><li>이 질문들은 <strong>원칙에서 결과로</strong> 시선을 옮기게 한다 → 벤담.</li></ul><h2 id="_2-칸트-복습과-한계-슬라이드-3-4쪽" tabindex="-1">2. 칸트 복습과 한계 (슬라이드 3~4쪽) <a class="header-anchor" href="#_2-칸트-복습과-한계-슬라이드-3-4쪽" aria-label="Permalink to &quot;2. 칸트 복습과 한계 (슬라이드 3~4쪽)&quot;">​</a></h2><ul><li>복습: <strong>선의지·의무·정언명령</strong>. 정언명령의 세 정식 — <strong>보편법칙</strong>(준칙을 보편법칙으로 의욕할 수 있나), <strong>인간성</strong>(사람을 단순한 수단으로만 대하지 말 것), <strong>자율성</strong>(모든 이성적 존재가 스스로 부여한 법칙으로 받아들일 수 있나). 이들은 이성적 행위 능력·자율성·존엄성을 보호한다. → <a href="./10. 정언명령, 보편법칙의 정식, 완전·불완전 의무.html">10. 정언명령, 보편법칙의 정식, 완전·불완전 의무</a>, <a href="./11. 정언명령의 보편화 검사와 칸트 윤리의 평가(5주차 온라인).html">11. 정언명령의 보편화 검사와 칸트 윤리의 평가(5주차 온라인)</a></li><li>칸트의 한계로 제기된 문제들: <ul><li><strong>결과</strong>: 피할 수 있는 고통도 도덕적으로 고려되어야 한다.</li><li><strong>의무의 충돌</strong>: 형식적 원칙만으로는 의무 사이 갈등을 해결하기 어렵다.</li><li><strong>긴급 상황·공공정책</strong>: 집단을 다스리려면 결과와 제한된 자원을 고려해야 한다.</li><li><strong>의존·돌봄·비인간 동물</strong>: 도덕적 지위를 이성적 능력에 두면 의존적·비이성적 존재가 배제된다.</li></ul></li></ul><h2 id="_3-전환-칸트-→-벤담-슬라이드-5쪽" tabindex="-1">3. 전환: 칸트 → 벤담 (슬라이드 5쪽) <a class="header-anchor" href="#_3-전환-칸트-→-벤담-슬라이드-5쪽" aria-label="Permalink to &quot;3. 전환: 칸트 → 벤담 (슬라이드 5쪽)&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>칸트</th><th>벤담</th></tr></thead><tbody><tr><td>질문</td><td>모든 이성적 행위자가 보편법칙으로 받아들일 수 있는 원칙은?</td><td>어떤 행위·정책이 쾌락과 고통의 <strong>최대 균형</strong>을 낳는가?</td></tr><tr><td>출발점</td><td><strong>의무</strong>, 준칙 평가</td><td><strong>복지</strong>, 행위의 결과 평가</td></tr><tr><td>강조</td><td>이성적 일관성, 인격을 수단으로만 대하지 않기</td><td><strong>경험된 결과</strong>, 예방 가능한 고통을 무시하지 않기</td></tr></tbody></table><ul><li>각 이론은 서로 다른 도덕적 특징을 드러낸다.</li></ul><h2 id="_4-벤담의-생애와-시대-슬라이드-6쪽" tabindex="-1">4. 벤담의 생애와 시대 (슬라이드 6쪽) <a class="header-anchor" href="#_4-벤담의-생애와-시대-슬라이드-6쪽" aria-label="Permalink to &quot;4. 벤담의 생애와 시대 (슬라이드 6쪽)&quot;">​</a></h2><ul><li>제러미 벤담(1748–1832): 영국의 철학자·법학자·정치이론가·사회개혁가. 어린 나이에 옥스퍼드에 입학했고 영국법에 비판적이었다.</li><li>법은 <strong>인간의 복지에 미치는 영향</strong>으로 판단해야 한다고 믿었다. 흄·베카리아·계몽주의 개혁가들의 영향.</li><li>요약 강조점: 벤담은 <strong>오래됐다는 이유만으로 법과 제도가 정당화되지 않는다</strong>고 보았고, 실제로 고통을 줄이고 행복을 늘리는지로 제도를 평가하려 했다.</li></ul><h2 id="_5-왜-측정-인가-슬라이드-7쪽" tabindex="-1">5. 왜 &quot;측정&quot;인가 (슬라이드 7쪽) <a class="header-anchor" href="#_5-왜-측정-인가-슬라이드-7쪽" aria-label="Permalink to &quot;5. 왜 &quot;측정&quot;인가 (슬라이드 7쪽)&quot;">​</a></h2><ol><li>공공정책은 <strong>비교</strong>가 필요하다 — 공통된 평가 기준.</li><li>쾌락·고통은 누구나 인식하는 <strong>공개적으로 이해 가능한 기준</strong>.</li><li>측정은 <strong>특권에 도전</strong>한다 — 모든 쾌락이 동등하면 사회적 지위만으로 우대할 수 없다.</li><li>법 개혁은 <strong>비례성</strong>을 요구한다 — 처벌은 국가가 가하는 고통이므로 필요 이상이면 안 된다.</li><li>분류·행정에 대한 근대적 신뢰 — 자의적 권력을 드러내기도, 감시·통제를 가능케도 한다.</li></ol><ul><li>요약의 단서: 계량화는 특권과 자의적 권위에 도전할 수 있지만, <strong>가정을 숨기고 사회적 편견을 재생산하며 일부 경험을 보이지 않게</strong> 만들 수도 있다.</li></ul><h2 id="_6-핵심-개념-슬라이드-8-9쪽" tabindex="-1">6. 핵심 개념 (슬라이드 8~9쪽) <a class="header-anchor" href="#_6-핵심-개념-슬라이드-8-9쪽" aria-label="Permalink to &quot;6. 핵심 개념 (슬라이드 8~9쪽)&quot;">​</a></h2><ul><li><strong>결과주의</strong>: 행위는 그것이 낳는(또는 낳을 것으로 예상되는) 결과로 평가한다.</li><li><strong>공리의 원리(principle of utility)</strong>: 효용(utility)은 단순한 실용성이 아니라 행위가 이익·쾌락·선·행복을 늘리고 해악·고통·악·불행을 막는 <strong>경향</strong>. 간단히 말해 행위의 가치는 <strong>영향받는 모든 사람의 쾌락과 고통의 예상 총균형</strong>으로 정해진다.</li><li><strong>쾌락주의</strong>: 쾌락은 그 자체로 선, 고통은 그 자체로 악.</li><li><strong>공평한 집계(impartial aggregation)</strong>: 사회적 지위와 관계없이 모든 사람의 쾌락이 동등하게 중요하다. &quot;내&quot; 쾌락이라고 더 쳐 주지 않고, 가난한 사람·수감자·<strong>비인간 동물</strong>의 고통도 힘이 없다고 무시할 수 없다 → 평등주의적 잠재력.</li><li><strong>심리적 쾌락주의 vs 윤리적 쾌락주의</strong><ul><li>심리적: <strong>서술적</strong>. 사람들은 실제로 쾌락을 추구하고 고통을 피한다.</li><li>윤리적: <strong>규범적</strong>. 쾌락을 늘리고 고통을 줄여야 한다.</li><li>둘은 같지 않다. 사람들이 쾌락을 <em>추구한다</em>는 사실이 곧 <em>모든 이의 쾌락을 증진해야 한다</em>는 결론이 되지는 않는다 — 벤담 철학의 핵심 긴장.</li></ul></li></ul><h2 id="_7-양적-공리주의-슬라이드-10쪽" tabindex="-1">7. 양적 공리주의 (슬라이드 10쪽) <a class="header-anchor" href="#_7-양적-공리주의-슬라이드-10쪽" aria-label="Permalink to &quot;7. 양적 공리주의 (슬라이드 10쪽)&quot;">​</a></h2><ul><li>쾌락과 고통을 <strong>양과 여러 차원</strong>으로 비교하기 때문에 &quot;양적&quot; 공리주의라 부른다. 고급·저급 쾌락의 <strong>본질적 위계</strong>를 두지 않는다.</li><li>지적 쾌락이 식사 같은 육체적 쾌락보다 <strong>고상하다는 이유만으로</strong> 우월하지는 않다. 더 가치 있다면 지속성·미래 효과·부정적 후속의 부재 같은 구체적 차원으로 설명해야 한다.</li><li><strong>쾌락 계산법(felicific calculus)의 7차원</strong></li></ul><table tabindex="0"><thead><tr><th>차원</th><th>뜻</th></tr></thead><tbody><tr><td>강도(Intensity)</td><td>쾌락·고통의 세기</td></tr><tr><td>지속성(Duration)</td><td>얼마나 오래 가나</td></tr><tr><td>확실성(Certainty)</td><td>실제로 발생할 가능성</td></tr><tr><td>근접성(Propinquity)</td><td>시간적으로 얼마나 가까운가</td></tr><tr><td>다산성(Fecundity)</td><td>같은 종류의 감각이 이어질 가능성</td></tr><tr><td>순수성(Purity)</td><td>반대 감각이 뒤따르지 않을 가능성</td></tr><tr><td>범위(Extent)</td><td>영향받는 사람의 수</td></tr></tbody></table><ul><li>이 7차원은 <strong>정밀한 수학 공식이 아니라</strong> 여러 행위·정책의 예상 결과를 체계적으로 비교하는 <strong>판단의 틀</strong>이다.</li><li>강의가 든 적용 예: 공공보건 정책, 교육, 중독적 디지털 플랫폼, 형벌, 기후변화, 대학 예산 배분.</li></ul><h2 id="_8-정독-『도덕과-입법의-원리-서설』-4장-29-30쪽-슬라이드-11-12쪽" tabindex="-1">8. 정독: 『도덕과 입법의 원리 서설』 4장, 29~30쪽 (슬라이드 11~12쪽) <a class="header-anchor" href="#_8-정독-『도덕과-입법의-원리-서설』-4장-29-30쪽-슬라이드-11-12쪽" aria-label="Permalink to &quot;8. 정독: 『도덕과 입법의 원리 서설』 4장, 29~30쪽 (슬라이드 11~12쪽)&quot;">​</a></h2><ul><li>슬라이드는 <strong>다산성</strong>과 <strong>순수성</strong>을 정독한다. 다산성 — 쾌락이 추가 쾌락으로(또는 고통이 추가 고통으로) 이어질 확률. 순수성 — 쾌락 뒤에 고통이(또는 고통 뒤에 쾌락이) 따르지 않을 확률. <strong>도덕적 순수성이 아니라 기술적 용어</strong>.</li><li>벤담은 이 두 차원이 엄밀히는 쾌락·고통 <em>자체</em>의 속성이 아니라, 그것을 낳은 <strong>행위나 사건의 속성</strong>으로 보아야 한다고 한다.</li><li>요약에는 이 정독 세부가 없고 7차원 목록만 나온다.</li></ul><h2 id="_9-절차-한-사람에서-다수로-슬라이드-13쪽" tabindex="-1">9. 절차: 한 사람에서 다수로 (슬라이드 13쪽) <a class="header-anchor" href="#_9-절차-한-사람에서-다수로-슬라이드-13쪽" aria-label="Permalink to &quot;9. 절차: 한 사람에서 다수로 (슬라이드 13쪽)&quot;">​</a></h2><ul><li>요약은 직접 언급하지 않지만, 슬라이드의 6단계: 한 사람에서 시작 → 즉각적 쾌락 파악 → 즉각적 고통 파악 → 이후 결과 추적 → 영향받는 각 사람에게 반복 → <strong>개인별로 먼저 검토한 뒤 합산·비교</strong>.</li></ul><h2 id="_10-주요-반론-슬라이드-14-15쪽-요약" tabindex="-1">10. 주요 반론 (슬라이드 14~15쪽 + 요약) <a class="header-anchor" href="#_10-주요-반론-슬라이드-14-15쪽-요약" aria-label="Permalink to &quot;10. 주요 반론 (슬라이드 14~15쪽 + 요약)&quot;">​</a></h2><ul><li><strong>측정의 문제</strong>: 쾌락·고통에 자연적 수치 기준이 없다.</li><li><strong>개인 간 비교</strong>: 타인의 고통을 직접 경험할 수 없고, 역사적 편견이 소외 집단의 계산을 왜곡해 왔다.</li><li><strong>권리와 개인의 희생</strong>: 다수의 쾌락이 소수의 심각한 고통을 압도할 수 있고, 개인이 결과를 넘어선 <strong>권리</strong>를 갖는지 의문. (요약: 집계 안에서 개인이 불가침의 권리를 갖는 것은 아니다)</li><li>슬라이드에만 나오는 반론: 정의·분배(같은 총량이 불공정을 숨김), 소수자 억압, 쾌락의 <strong>질</strong>(→ 밀의 고급/저급 쾌락 구분), <strong>경험기계</strong>, <strong>과도한 요구</strong>.</li></ul><h2 id="_11-현대적-적용-슬라이드-16-17쪽" tabindex="-1">11. 현대적 적용 (슬라이드 16~17쪽) <a class="header-anchor" href="#_11-현대적-적용-슬라이드-16-17쪽" aria-label="Permalink to &quot;11. 현대적 적용 (슬라이드 16~17쪽)&quot;">​</a></h2><ul><li>요약이 든 영역: 공중보건, 교육, 중독적 플랫폼, 형벌, 기후변화, 대학 자원 배분.</li><li>슬라이드가 덧붙인 것: <strong>참여 극대화 ≠ 효용 극대화</strong>(불안·양극화·의존을 숨기는 대리 지표), 알고리즘 복지 결정의 오류(소득 손실·굴욕·주거 불안), 의료 <strong>트리아지</strong>(평등한 존중·비차별 함께), 기후 피해(현재 시민만의 계산은 불충분).</li><li><strong>동물 윤리</strong> (슬라이드 17쪽): 벤담의 결정적 질문 — 문제는 이성이나 말이 아니라 <strong>고통을 느낄 수 있는가</strong>. 도덕적 지위의 근거가 합리성이 아니라 <strong>감각 능력</strong>. 공리주의는 인간 이익이 더 크면 동물의 고통을 허용할 수도 있지만, 동물권론은 그런 상충 관계 자체를 거부한다.</li></ul><h2 id="_12-두-가지-필수-질문과-핵심-정리-슬라이드-18쪽" tabindex="-1">12. 두 가지 필수 질문과 핵심 정리 (슬라이드 18쪽) <a class="header-anchor" href="#_12-두-가지-필수-질문과-핵심-정리-슬라이드-18쪽" aria-label="Permalink to &quot;12. 두 가지 필수 질문과 핵심 정리 (슬라이드 18쪽)&quot;">​</a></h2><ul><li><strong>칸트의 질문</strong>: &quot;우리가 어떤 사람에게도 절대 해서는 안 되는 일은 무엇인가?&quot;</li><li><strong>벤담의 질문</strong>: &quot;우리의 행동이 실제로 어떤 고통을 낳을 것인가?&quot;</li><li>벤담의 업적: <strong>경험된 고통을 도덕적·정치적으로 가시화</strong>했다 — 의도가 아니라 <strong>결과</strong>.</li><li>요약의 핵심: 벤담은 도덕 판단을 <em>보편 원칙에 대한 복종</em>의 문제에서 <strong>경험된 결과를 비교·평가하는 문제</strong>로 옮겼다. 중요한 질문은 &quot;이 행위가 보편화될 수 있는가?&quot;만이 아니라 <strong>&quot;누구에게, 얼마나 강하게, 얼마나 오래, 얼마나 확실하게, 어떤 후속 효과와 함께 쾌락·고통을 낳는가?&quot;</strong> 이다.</li><li>다음 주: <strong>밀</strong> — 쾌락은 양뿐 아니라 <strong>질</strong>에서도 다르다.</li></ul><h2 id="개념-깊이-보기" tabindex="-1">개념 깊이 보기 <a class="header-anchor" href="#개념-깊이-보기" aria-label="Permalink to &quot;개념 깊이 보기&quot;">​</a></h2><h3 id="_7차원은-세-층으로-쌓인다" tabindex="-1">7차원은 세 층으로 쌓인다 <a class="header-anchor" href="#_7차원은-세-층으로-쌓인다" aria-label="Permalink to &quot;7차원은 세 층으로 쌓인다&quot;">​</a></h3><p>원문 4장의 순서를 따라가면 7차원은 한 번에 나열되는 목록이 아니라 <strong>평가 대상이 넓어지면서 하나씩 추가되는 구조</strong>다.</p><table tabindex="0"><thead><tr><th>층</th><th>평가 대상</th><th>차원</th><th>원문 위치</th></tr></thead><tbody><tr><td>①</td><td><strong>감각 하나 그 자체</strong> (한 사람, 한 쾌락)</td><td>강도·지속성·확실성·근접성</td><td>4장 Ⅱ</td></tr><tr><td>②</td><td>그 감각을 낳은 <strong>행위의 경향</strong></td><td>+ 다산성·순수성</td><td>4장 Ⅲ (30쪽)</td></tr><tr><td>③</td><td>그 행위가 영향을 주는 <strong>여러 사람</strong></td><td>+ 범위</td><td>Ⅲ 다음 문단 (암기 시의 &quot;extend&quot;가 예고)</td></tr></tbody></table><p>슬라이드 13쪽의 6단계 절차(한 사람 → 즉각적 쾌락·고통 → 이후 결과 → 모든 사람에게 반복 → 합산)가 이 세 층을 그대로 밟는다. 그래서 다산성·순수성이 &quot;쾌락 자체가 아니라 <strong>행위의</strong> 속성&quot;이라는 벤담의 단서가 중요하다 — 다산성·순수성을 넣는 순간 평가 대상이 감각에서 행위로 바뀐다.</p><h3 id="순수성은-높을수록-좋다-가-아니다" tabindex="-1">순수성은 &quot;높을수록 좋다&quot;가 아니다 <a class="header-anchor" href="#순수성은-높을수록-좋다-가-아니다" aria-label="Permalink to &quot;순수성은 &quot;높을수록 좋다&quot;가 아니다&quot;">​</a></h3><p>순수성 = <strong>반대 감각이 섞이지 않는 정도</strong>일 뿐 가치 판단이 아니다.</p><table tabindex="0"><thead><tr><th></th><th>순수성 높음</th><th>순수성 낮음</th></tr></thead><tbody><tr><td><strong>쾌락</strong></td><td>뒤탈 없는 쾌락 → 좋음</td><td>SNS 몰아보기 → 불안·자책이 따라옴 → <strong>나쁨</strong></td></tr><tr><td><strong>고통</strong></td><td>아무 보상 없는 고통 → 나쁨</td><td>운동·수술 → 건강·회복이 따라옴 → <strong>좋음</strong></td></tr></tbody></table><p>즉 <strong>쾌락은 순수할수록, 고통은 불순할수록</strong> 좋다.</p><h3 id="심리적-→-윤리적-쾌락주의의-간극과-칸트" tabindex="-1">심리적 → 윤리적 쾌락주의의 간극과 칸트 <a class="header-anchor" href="#심리적-→-윤리적-쾌락주의의-간극과-칸트" aria-label="Permalink to &quot;심리적 → 윤리적 쾌락주의의 간극과 칸트&quot;">​</a></h3><p>&quot;사람들은 쾌락을 추구한다&quot;(사실)에서 &quot;모든 사람의 쾌락을 늘려야 한다&quot;(당위)는 바로 나오지 않는다. 이 간극은 칸트가 4주차에 짚은 바로 그 지점이다 — <strong>경험은 사람들이 무엇을 하는지만 알려줄 뿐, 무엇을 해야 하는지는 알려주지 못한다.</strong> 칸트는 이 때문에 도덕을 선험적 이성에 세웠고, 벤담은 경험된 쾌락·고통에서 출발하므로 이 간극을 메워야 하는 부담을 진다. 게다가 심리적 쾌락주의가 말하는 것은 <strong>자기</strong> 쾌락이지만, 윤리적 쾌락주의(공평한 집계)는 <strong>모두의</strong> 쾌락을 요구한다 — 이기적 동기에서 공평한 의무로의 이행도 설명이 필요하다.</p><h3 id="같은-사례를-칸트와-벤담은-다르게-비판한다" tabindex="-1">같은 사례를 칸트와 벤담은 다르게 비판한다 <a class="header-anchor" href="#같은-사례를-칸트와-벤담은-다르게-비판한다" aria-label="Permalink to &quot;같은 사례를 칸트와 벤담은 다르게 비판한다&quot;">​</a></h3><table tabindex="0"><thead><tr><th>사례</th><th>칸트 (5주차)</th><th>벤담 (6주차)</th></tr></thead><tbody><tr><td>참여 극대화 플랫폼</td><td>준칙(&quot;성찰과 무관하게 주의를 포획한다&quot;)이 사용자의 <strong>자율적 판단을 우회</strong> → 이성적 행위 능력 훼손</td><td>쾌락이 <strong>순수성 낮음</strong>(불안·의존), <strong>범위</strong> 막대 → 대리 지표가 진짜 효용을 숨김</td></tr><tr><td>거짓 약속</td><td>보편화하면 약속 제도가 사라짐 → <strong>개념상 모순</strong></td><td>신뢰 붕괴가 낳는 고통의 <strong>다산성</strong> → 안정된 규칙이 더 큰 효용</td></tr><tr><td>돕기의 의무</td><td><strong>불완전 의무</strong> — 구속력은 있지만 언제·얼마나는 재량</td><td>더 큰 효용이 나는 한 계속 요구 → <strong>과도한 요구</strong> 반론</td></tr></tbody></table><p>마지막 행이 두 이론의 차이를 잘 보여 준다. 칸트는 돕는 의무에 <strong>재량의 여지</strong>를 구조적으로 넣어 두었지만, 공리주의는 &quot;최대&quot;를 요구하므로 의무가 어디서 멈추는지 말하기 어렵다.</p><h3 id="측정의-양면-—-판옵티콘" tabindex="-1">측정의 양면 — 판옵티콘 <a class="header-anchor" href="#측정의-양면-—-판옵티콘" aria-label="Permalink to &quot;측정의 양면 — 판옵티콘&quot;">​</a></h3><p>슬라이드 7쪽의 다섯째 항목(&quot;분류와 행정에 대한 근대적 신뢰는 자의적 권력을 드러내지만 감시와 통제도 가능하게 한다&quot;)의 상징이 벤담 자신이 설계한 감옥 <strong>판옵티콘</strong>이다. 중앙 감시탑에서 모든 수감자를 볼 수 있지만 수감자는 감시자를 볼 수 없어, 실제로 감시하지 않아도 스스로 행동을 규율하게 만든다. 고통(처벌)을 최소 비용으로 관리하려는 공리주의적 개혁 정신이 동시에 <strong>감시 사회의 원형</strong>이 될 수 있다는 것 — 반론 ⑩(전문가 행정과 시민의 자율)과 이어진다.</p><h3 id="경험-기계-—-쾌락주의에-대한-반례" tabindex="-1">경험 기계 — 쾌락주의에 대한 반례 <a class="header-anchor" href="#경험-기계-—-쾌락주의에-대한-반례" aria-label="Permalink to &quot;경험 기계 — 쾌락주의에 대한 반례&quot;">​</a></h3><p>노직의 사고실험이다. 평생 원하는 쾌락을 그대로 느끼게 해 주는 기계에 들어가겠는가? 쾌락주의가 옳다면 거절할 이유가 없는데, 대부분은 거절한다. 우리는 우정의 <strong>느낌</strong>이 아니라 <strong>실제 우정</strong>, 성취감이 아니라 <strong>실제 성취</strong>를 원한다. 이는 공리주의 전체가 아니라 그 바탕의 <strong>쾌락주의</strong>(쾌락만이 본질적으로 선하다)를 겨냥한 반론이다.</p><hr><p><em>출처: 6주차 온라인 강의 6-1, 6-2 요약 자료(윤지영 교수 제공, 영문+국문)와 <code>26-2 윤리학 6강.pdf</code> 슬라이드를 바탕으로 직접 재구성. 슬라이드 위치는 요약 주제와 슬라이드 제목을 대조해 추정했고, 요약에 없는 슬라이드 내용은 해당 항목에 별도로 표시함.</em></p>',52)])])}const c=r(e,[["render",i]]);export{_ as __pageData,c as default};
